if (!function_exists('getBackendEventBaseType')) {
    function getBackendEventBaseType(string $label): string {
        $u = strtoupper($label);
        
        $is10mPistolParaDeaf = (strpos($u, '10M AIR PISTOL') !== false || strpos($u, '10M PISTOL') !== false) && 
            (strpos($u, 'SH1') !== false || strpos($u, 'DEAF') !== false || strpos($u, 'PARA') !== false || strpos($u, 'DS12') !== false || strpos($u, 'DS13') !== false || strpos($u, 'R021') !== false || strpos($u, 'R022') !== false || strpos($u, 'R023') !== false || strpos($u, 'R024') !== false || strpos($u, 'R025') !== false || strpos($u, 'R026') !== false || strpos($u, 'R031') !== false || strpos($u, 'R032') !== false);

        $suffix = '';
        if ($is10mPistolParaDeaf || strpos($u, '(ISSF)') !== false || strpos($u, ' ISSF') !== false) {
            $suffix = '_issf';
        } elseif (strpos($u, '(NR)') !== false || strpos($u, ' NR') !== false || strpos($u, 'NATIONAL RULE') !== false) {
            $suffix = '_nr';
        }

        $base = '';
        if (strpos($u, '10M AIR RIFLE STANDING SH1') !== false) $base = '10m_air_rifle_standing_sh1';
        elseif (strpos($u, '10M AIR RIFLE PRONE SH1') !== false) $base = '10m_air_rifle_prone_sh1';
        elseif (strpos($u, '50M RIFLE PRONE SH1') !== false) $base = '50m_rifle_prone_sh1';
        elseif (strpos($u, '50M RIFLE 3 POSITIONS SH1') !== false || strpos($u, '50M RIFLE 3 POSITION SH1') !== false) $base = '50m_rifle_3_positions_sh1';
        elseif (strpos($u, '10M AIR RIFLE STANDING SH2') !== false) $base = '10m_air_rifle_standing_sh2';
        elseif (strpos($u, '10M AIR RIFLE PRONE SH2') !== false) $base = '10m_air_rifle_prone_sh2';
        elseif (strpos($u, '50M RIFLE PRONE SH2') !== false) $base = '50m_rifle_prone_sh2';
        elseif (!$is10mPistolParaDeaf && strpos($u, '10M AIR PISTOL SH1') !== false) $base = '10m_air_pistol_sh1';
        elseif (strpos($u, '25M PISTOL SH1') !== false) $base = '25m_pistol_sh1';
        elseif (strpos($u, '50M PISTOL SH1') !== false) $base = '50m_pistol_sh1';
        elseif (strpos($u, '10M STANDARD AIR PISTOL SH1') !== false) $base = '10m_standard_air_pistol_sh1';
        
        elseif (strpos($u, '10M OPEN SIGHT AIR RIFLE') !== false || strpos($u, 'OPEN SIGHT') !== false) $base = '10m_open_sight_air_rifle';
        elseif (strpos($u, '10M PEEP SIGHT AIR RIFLE') !== false || strpos($u, 'PEEP RIFLE') !== false || strpos($u, 'PEEP SIGHT') !== false || strpos($u, '10M AIR RIFLE') !== false || strpos($u, '10M RIFLE') !== false) $base = 'peep_rifle';
        elseif (strpos($u, '50M OPEN SIGHT RIFLE PRONE') !== false) $base = '50m_open_sight_rifle_prone';
        elseif (strpos($u, '50M RIFLE PRONE') !== false) $base = '50m_rifle_prone';
        elseif (strpos($u, '50M OPEN SIGHT RIFLE 3 POSITIONS') !== false || strpos($u, '50M OPEN SIGHT RIFLE 3 POSITION') !== false) $base = '50m_open_sight_rifle_3_positions';
        elseif (strpos($u, '50M RIFLE 3 POSITIONS') !== false || strpos($u, '50M RIFLE 3 POSITION') !== false || strpos($u, '50M RIFLE 3P') !== false) $base = '50m_rifle_3_positions';
        
        elseif (strpos($u, '10M AIR PISTOL') !== false || strpos($u, '10M PISTOL') !== false) $base = '10m_air_pistol';
        elseif (strpos($u, '25M SPORTS PISTOL') !== false || strpos($u, '25M SPORT PISTOL') !== false || strpos($u, '25M PISTOL') !== false) $base = '25m_sport_pistol';
        elseif (strpos($u, '25M CENTRE FIRE PISTOL') !== false || strpos($u, '25M CENTER FIRE PISTOL') !== false || strpos($u, '25M CENTRE') !== false || strpos($u, '25M CENTER') !== false) $base = '25m_centre_fire_pistol';
        elseif (strpos($u, '25M STANDARD PISTOL') !== false || strpos($u, '25M STANDARD') !== false) $base = '25m_standard_pistol';
        elseif (strpos($u, '50M FREE PISTOL') !== false || strpos($u, '50M PISTOL') !== false || strpos($u, '50M FREE') !== false) $base = '50m_free_pistol';

        if (empty($base)) {
            $cleanName = preg_replace('/\s*\([^)]*\)/', '', $label);
            $cleanName = preg_replace('/\b(CHAMPIONSHIP|MEN|WOMEN|INDIVIDUAL|TEAM|MIXED|SH1|SH2|SUB|YOUTH|JUNIOR|SENIOR|MASTER|SUPER|PEEP|SIGHT)\b/i', '', $cleanName);
            $base = preg_replace('/[^a-zA-Z0-9]/', '_', strtolower(trim($cleanName)));
            $base = preg_replace('/_+/', '_', $base);
            $base = trim($base, '_');
            $base = preg_replace('/_(issf|nr|nr_mqs)$/i', '', $base);
        }
        return $base . $suffix;
    }
}

if (!function_exists('getRangeCapacity')) {
    function getRangeCapacity(string $eventName): int {
        global $EVENTS_MAPPING;
        $u = strtoupper($eventName);
        if (isset($EVENTS_MAPPING[$eventName])) {
            $u = strtoupper($EVENTS_MAPPING[$eventName]);
        }
        if (strpos($u, '50M') !== false || strpos($u, '50 M') !== false || strpos($u, '50METERS') !== false) {
            return 24;
        }
        if (strpos($u, '25M') !== false || strpos($u, '25 M') !== false || strpos($u, '25METERS') !== false) {
            return 28;
        }
        if (strpos($u, '10M') !== false || strpos($u, '10 M') !== false || strpos($u, '10METERS') !== false) {
            return 40;
        }
        return 40; // Default fallback
    }
}

if (!function_exists('getRangeType')) {
    function getRangeType(string $eventName): string {
        global $EVENTS_MAPPING;
        $u = strtoupper($eventName);
        if (isset($EVENTS_MAPPING[$eventName])) {
            $u = strtoupper($EVENTS_MAPPING[$eventName]);
        }
        if (strpos($u, '50M') !== false || strpos($u, '50 M') !== false || strpos($u, '50METERS') !== false) {
            return '50M';
        }
        if (strpos($u, '25M') !== false || strpos($u, '25 M') !== false || strpos($u, '25METERS') !== false) {
            return '25M';
        }
        return '10M';
    }
}

if (!function_exists('formatBaseEventName')) {
    function formatBaseEventName(string $baseType): string {
        $suffix = '';
        $cleanType = $baseType;
        if (substr($baseType, -5) === '_issf') {
            $suffix = ' (ISSF)';
            $cleanType = substr($baseType, 0, -5);
        } elseif (substr($baseType, -3) === '_nr') {
            $suffix = ' (NR)';
            $cleanType = substr($baseType, 0, -3);
        }

        $mapping = [
            '10m_air_rifle_standing_sh1' => '10m Air Rifle Standing SH1',
            '10m_air_rifle_prone_sh1' => '10m Air Rifle Prone SH1',
            '50m_rifle_prone_sh1' => '50m Rifle Prone SH1',
            '50m_rifle_3_positions_sh1' => '50m Rifle 3 Positions SH1',
            '10m_air_rifle_standing_sh2' => '10m Air Rifle Standing SH2',
            '10m_air_rifle_prone_sh2' => '10m Air Rifle Prone SH2',
            '50m_rifle_prone_sh2' => '50m Rifle Prone SH2',
            '10m_air_pistol_sh1' => '10m Air Pistol SH1',
            '25m_pistol_sh1' => '25m Pistol SH1',
            '50m_pistol_sh1' => '50m Pistol SH1',
            '10m_standard_air_pistol_sh1' => '10m Standard Air Pistol SH1',
            '10m_open_sight_air_rifle' => '10m Open Sight Air Rifle',
            '10m_air_rifle' => '10m Peep Sight Air Rifle',
            'peep_rifle' => '10m Peep Sight Air Rifle',
            'peep_sight_rifle' => '10m Peep Sight Air Rifle',
            '50m_open_sight_rifle_prone' => '50m Open Sight Rifle Prone',
            '50m_rifle_prone' => '50m Rifle Prone',
            '50m_open_sight_rifle_3_positions' => '50m Open Sight Rifle 3 Positions',
            '50m_rifle_3_positions' => '50m Rifle 3 Positions',
            '10m_air_pistol' => '10m Air Pistol',
            '25m_sport_pistol' => '25m Sports Pistol',
            '25m_centre_fire_pistol' => '25m Centre Fire Pistol',
            '25m_standard_pistol' => '25m Standard Pistol',
            '50m_free_pistol' => '50m Free Pistol',
        ];
        $name = $mapping[$cleanType] ?? ucwords(str_replace('_', ' ', $cleanType));
        return $name . $suffix;
    }
}

if (!function_exists('extractEventCategory')) {
    function extractEventCategory(string $fullEventName, string $baseType): string {
        $baseFormatted = formatBaseEventName($baseType);
        
        $cleanFull = trim(str_replace(['(ISSF)', '(NR)', 'ISSF', 'NR'], '', strtoupper($fullEventName)));
        $cleanBase = trim(str_replace(['(ISSF)', '(NR)', 'ISSF', 'NR'], '', strtoupper($baseFormatted)));
        
        $category = $fullEventName;
        if (strpos($cleanFull, $cleanBase) === 0) {
            $category = substr($cleanFull, strlen($cleanBase));
        } else {
            $aliases = [
                '10M AIR RIFLE', '10M RIFLE', '10M AIR PISTOL', '10M PISTOL',
                '50M RIFLE PRONE', '50M FREE RIFLE 3P', '50M RIFLE 3 POSITIONS',
                '50M RIFLE 3 POSITION', '50M RIFLE 3P', '50M FREE RIFLE', '50M PISTOL',
                '25M CENTRE FIRE PISTOL', '25M CENTER FIRE PISTOL', '25M STANDARD PISTOL',
                '25M SPORTS PISTOL', '25M SPORT PISTOL', '25M PISTOL', '50M FREE PISTOL'
            ];
            foreach ($aliases as $alias) {
                if (strpos($cleanFull, $alias) === 0) {
                    $category = substr($cleanFull, strlen($alias));
                    break;
                }
            }
        }
        
        $category = trim($category, " \t\n\r\0\x0B-_()");
        return empty($category) ? 'Open' : ucwords(strtolower($category));
    }
}

