/**
 * Overlays dynamic event definitions from database table `events` for active championship.
 */
if (!function_exists('loadDynamicEventsMapping')) {
    function loadDynamicEventsMapping(): array {
        global $EVENTS_MAPPING;
        if (!is_array($EVENTS_MAPPING)) {
            $EVENTS_MAPPING = [];
        }
        try {
            if (function_exists('getDB')) {
                $pdo = getDB();
                if ($pdo) {
                    $active = function_exists('getActiveChampionship') ? getActiveChampionship($pdo) : null;
                    $cid = (int)($active['id'] ?? 1);
                    $stmt = $pdo->prepare("SELECT event_code, event_name FROM `events` WHERE `championship_id` = ? AND (`status` IS NULL OR `status` = 'active') ORDER BY id ASC");
                    $stmt->execute([$cid]);
                    $dbEvents = $stmt->fetchAll(PDO::FETCH_ASSOC);

                    if (empty($dbEvents)) {
                        $stmtFb = $pdo->query("SELECT event_code, event_name FROM `events` WHERE `status` IS NULL OR `status` = 'active' ORDER BY id ASC");
                        $dbEvents = $stmtFb->fetchAll(PDO::FETCH_ASSOC);
                    }

                    foreach ($dbEvents as $ev) {
                        $code = strtoupper(trim((string)$ev['event_code']));
                        $name = trim((string)$ev['event_name']);
                        if ($code !== '' && $name !== '') {
                            $EVENTS_MAPPING[$code] = $name;
                            $cleanCode = str_replace(['-', ' '], '', $code);
                            $EVENTS_MAPPING[$cleanCode] = $name;
                        }
                    }
                }
            }
        } catch (Throwable $t) {}
        return $EVENTS_MAPPING;
    }
}

loadDynamicEventsMapping();
